<?php
/** Plugin Name: TEMP PS S1736o snippet 570 v1.1 DP puslapis su puslapiavimu (1 dry / 2 deploy / 3 patikra / 9 atstato) */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1736o'])) return;
  $f=$_GET['ps_s1736o']; @set_time_limit(250); global $wpdb; $T=$wpdb->prefix.'snippets'; $r=['v'=>'S1736o','faze'=>$f];
  $OLD='8b17aa9172226586fbd744b5ef885e19'; $NEW='436f0a193ca7008e145f773a12aef314'; $BAK='ps_s1736_snip570_bak';
  $get=function($u){ $x=wp_remote_get($u,['timeout'=>40,'sslverify'=>false,'headers'=>['Cookie'=>'ps_js=1']]); if(is_wp_error($x)) return ['ERR',$x->get_error_message()]; return [wp_remote_retrieve_response_code($x),wp_remote_retrieve_body($x)]; };
  $matuoti=function($q='') use($get){ $u=home_url('/daugiau-pigiau/?ps_hb='.time().rand(10,99).$q); list($c,$h)=$get($u); preg_match_all('~data-product_id="(\d+)"~',$h,$m); preg_match_all('~product-page=(\d+)~',$h,$p); $vis=''; if(preg_match('~Visos <span class="psc-dp-count">\((\d+)\)~',$h,$v)) $vis=$v[1]; return ['http'=>$c,'prekiu'=>count(array_unique($m[1])),'puslapiai'=>array_values(array_unique($p[1])),'visos'=>$vis]; };
  $kesas=function(){ $dir=WP_CONTENT_DIR.'/cache/supercache/'.wp_parse_url(home_url(),PHP_URL_HOST).'/daugiau-pigiau'; if(is_dir($dir)){ if(function_exists('prune_super_cache')) prune_super_cache($dir,true); else { foreach(glob($dir.'/*') as $x) @unlink($x); @rmdir($dir); } } return is_dir($dir)?'liko':'isvalyta'; };
  try{
    $s=$wpdb->get_row("SELECT id,code,active FROM $T WHERE id=570",ARRAY_A); $live=md5($s['code']); $nc=gzuncompress(base64_decode(''));
    $tok=true; try{ token_get_all("<?php\n".$nc,TOKEN_PARSE); }catch(Throwable $e){ $tok=$e->getMessage(); }
    $r['live']=$live; $r['live_ok']=$live===$OLD; $r['new_ok']=md5($nc)===$NEW; $r['tok']=$tok; $r['active']=$s['active'];
    if($f==='1'){ $r['pries']=$matuoti(); }
    if($f==='2'){
      if(!($live===$OLD && md5($nc)===$NEW && $tok===true)){ $r['STOP']=1; }
      else{ if(!get_option($BAK)) update_option($BAK,base64_encode(gzcompress($s['code'],9)),false);
        $wpdb->update($T,['code'=>$nc,'modified'=>current_time('mysql',1)],['id'=>570]);
        if(function_exists('\Code_Snippets\clean_snippets_cache')) \Code_Snippets\clean_snippets_cache($T); wp_cache_flush_group('code_snippets');
        $r['irasyta']=md5($wpdb->get_var("SELECT code FROM $T WHERE id=570"));
        $x=wp_remote_get(home_url('/?ps_hb='.time()),['timeout'=>25,'sslverify'=>false,'redirection'=>0]); $r['hb']=is_wp_error($x)?'ERR':wp_remote_retrieve_response_code($x);
        if(!is_int($r['hb'])||$r['hb']>=500){ $wpdb->update($T,['code'=>$s['code']],['id'=>570]); $r['ATSTATYTA']=1; }
        $r['kesas']=$kesas(); } }
    if($f==='3'){ $r['p1']=$matuoti(); $r['p2']=$matuoti('&product-page=2'); $r['p5']=$matuoti('&product-page=5'); $r['katems']=$matuoti('&gyvunas=katems'); $r['katems_p2']=$matuoti('&gyvunas=katems&product-page=2'); }
    if($f==='9'){ $b=get_option($BAK); if($b){ $wpdb->update($T,['code'=>gzuncompress(base64_decode($b))],['id'=>570]); $r['atstatyta']=md5($wpdb->get_var("SELECT code FROM $T WHERE id=570")); $r['kesas']=$kesas(); } }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
}, 1);
